export type ReviewDispatchMode =
  | { kind: "full-review" }
  | { kind: "reuse"; judgedHeadSha: string }
  | { kind: "discriminate-only"; judgedHeadSha: string }
  /** W1-T11729 — re-post the DELIVERED verdict of this exact head and input after GitHub's status regressed. Never a review. */
  | { kind: "restore"; judgedHeadSha: string; regressionKey: string };

/** Options derived when admitting this review, rather than facts read by the PR-view producer. */
export interface ReviewDispatchPr extends OpenPrView {
  excludeProviders?: readonly WorkerProviderId[];
}

/**
 * The default `gh` invocation for {@link buildSweepEffects}' `ghRunImpl` seam — a NAMED function
 * rather than an inline default so it is reachable by a test at all. Its one caller closes a pull
 * request, so a test that drove it through the effect would have to close one; called directly
 * with a harmless argv it exercises the same statement and proves the seam's default is the real
 * spawn rather than a stub that quietly does nothing.
 */
export function defaultSweepGhRun(file: string, args: readonly string[]): void {
  execFileSync(file, [...args], { stdio: "pipe" });
}

/**
 * The words a failed `git` spawn actually printed, for the `reason` these outcomes carry.
 *
 * `execFileSync`'s Error.message is only `Command failed: <the argv>` — it restates what we already
 * know and drops what git said. The diagnosis is on `.stderr`, which `stdio: "pipe"` captured.
 * MEASURED on #4946: a rebase that failed because no committer identity was configured reported
 * `conflict` with reason "Command failed: git -C … rebase origin/main", so a CI log showed
 * `+ 'conflict' - 'rebased'` and nothing about the cause; git's own "Please tell me who you are"
 * was sitting in a field nobody read. Falls back to the message when stderr is empty, so this can
 * only ever add detail.
 */
function spawnFailureText(error: unknown): string {
  const e = error as { stderr?: unknown; message?: unknown };
  const stderrText = e?.stderr === undefined || e?.stderr === null ? "" : String(e.stderr).trim();
  return stderrText.length > 0 ? stderrText : String(e?.message ?? error);
}

export type DirtyFleetRebaseOutcome =
  | { outcome: "rebased"; oldHeadSha: string; newHeadSha: string }
  | { outcome: "conflict"; reason: string }
  | { outcome: "lease-mismatch"; reason: string }
  | { outcome: "error"; reason: string };

type DirtyFleetRebaseGit = (
  file: string,
  args: readonly string[],
  opts?: { cwd?: string; stdio?: "pipe" | "ignore"; encoding?: BufferEncoding },
) => string;

function dirtyFleetRebaseStoppedOnConflict(
  worktreePath: string,
  run: (cwd: string, args: readonly string[]) => string,
): boolean {
  try {
    const rebaseStateExists = ["rebase-merge", "rebase-apply"].some((stateDir) => {
      const statePath = run(worktreePath, ["rev-parse", "--git-path", stateDir]).trim();
      return statePath.length > 0 && existsSync(statePath);
    });
    if (!rebaseStateExists) return false;
    return run(worktreePath, ["ls-files", "-u"]).trim().length > 0;
  } catch (_inspectionError) {
    // If the rebase failure also makes git's state unreadable, keep the legacy conflict path.
    return true;
  }
}

function defaultDirtyFleetRebaseGit(
  file: string,
  args: readonly string[],
  opts: { cwd?: string; stdio?: "pipe" | "ignore"; encoding?: BufferEncoding } = {},
): string {
  // The cut checks out the PR's bytes and runs post-checkout there, so it carries the leaf's overrides.
  const hardened = args[2] === "worktree" ? HOST_GIT_CONFIG.flatMap(([k, v]) => ["-c", `${k}=${v}`]) : [];
  return execFileSync(file, [...hardened, ...args], {
    cwd: opts.cwd,
    encoding: opts.encoding ?? "utf8",
    stdio: opts.stdio ?? "pipe",
    maxBuffer: 1 << 24,
  }) as string;
}

/**
 * W1-T6133 — the git seam for a tree cut at a PR's OWN head. It takes the `-C <worktreePath> …` argv
 * the callers' seams already build and runs it through the leaf (pinned gitdir, the harness's hooks);
 * a push goes through the push leaf, whose pre-push gate is the harness's copy, never the tree's.
 */
export function prHeadTreeGit(worktreePath: string): (file: string, args: readonly string[]) => string {
  return (file, args) => {
    if (args[0] !== "-C" || args[1] !== worktreePath) {
      throw new Error(`sweep: a PR-head tree step must address ${worktreePath} with -C; got ${args.slice(0, 2).join(" ")}`);
    }
    if (args[2] !== "push") return hostWorktreeGit(worktreePath, args.slice(2), { maxBuffer: 1 << 24 });
    worktreePushExec(worktreePath)(file, [...args], { stdio: "inherit" });
    return "";
  };
}

/** {@link rebaseDirtyFleetBranchViaGit}'s default: the managed checkout raw (CHECKOUT), its PR-head tree via the leaf. */
function dirtyFleetRebaseGit(repoDir: string, worktreePath: string): DirtyFleetRebaseGit {
  const tree = prHeadTreeGit(worktreePath);
  return (file, args, opts) => (args[1] === repoDir ? defaultDirtyFleetRebaseGit(file, args, opts) : tree(file, args));
}

/** Default for {@link BuildSweepEffectsDeps.planRepairGitImpl} — the real spawn, appended last
 *  as its own seam so a test injects a fake in its place and asserts the recorded call. */
function defaultPlanRepairGit(
  file: string,
  args: readonly string[],
  opts: { encoding?: BufferEncoding } = {},
): string {
  return execFileSync(file, [...args], { encoding: opts.encoding ?? "utf8", stdio: "pipe" }) as string;
}

export function rebaseDirtyFleetBranchViaGit(
  repoDir: string,
  worktreePath: string,
  pr: Pick<OpenPrView, "prNumber" | "headRefName" | "headSha">,
  deps: { git?: DirtyFleetRebaseGit; worktreeRemoveImpl?: typeof worktreeRemove; expectedMainSha?: string } = {},
): DirtyFleetRebaseOutcome {
  const branch = pr.headRefName;
  if (!branch) return { outcome: "error", reason: `PR #${pr.prNumber} has no headRefName to rebase` };
  const git = deps.git ?? dirtyFleetRebaseGit(repoDir, worktreePath);
  const remove = deps.worktreeRemoveImpl ?? worktreeRemove;
  const ref = `refs/heads/${branch}`;
  const remoteRef = `refs/remotes/origin/${branch}`;
  const run = (cwd: string, args: readonly string[]): string => git("git", ["-C", cwd, ...args], { encoding: "utf8", stdio: "pipe" });
  let worktreeCreated = false;
  try {
    mkdirSync(dirname(worktreePath), { recursive: true });
    run(repoDir, [
      "fetch",
      "--no-tags",
      "--quiet",
      "origin",
      "+refs/heads/main:refs/remotes/origin/main",
      `+${ref}:${remoteRef}`,
    ]);
    const observedHead = run(repoDir, ["rev-parse", remoteRef]).trim();
    if (observedHead !== pr.headSha) {
      return {
        outcome: "lease-mismatch",
        reason: `origin/${branch} moved from ${pr.headSha} to ${observedHead} before the rebase started`,
      };
    }
    if (deps.expectedMainSha !== undefined) {
      const observedMain = run(repoDir, ["rev-parse", "refs/remotes/origin/main"]).trim();
      if (observedMain !== deps.expectedMainSha) {
        return {
          outcome: "lease-mismatch",
          reason: `origin/main moved from the locally verified repair ${deps.expectedMainSha} to ${observedMain} before the rebase started`,
        };
      }
    }
    run(repoDir, ["worktree", "add", "--detach", worktreePath, pr.headSha]);
    worktreeCreated = true;
    try {
      run(worktreePath, ["rebase", "origin/main"]);
    } catch (error) {
      const reason = capStderrExcerpt(spawnFailureText(error), STDERR_EXCERPT_CAP);
      const stoppedOnConflict = dirtyFleetRebaseStoppedOnConflict(worktreePath, run);
      if (!stoppedOnConflict) return { outcome: "error", reason };
      try {
        run(worktreePath, ["rebase", "--abort"]);
      } catch {
        /* best-effort cleanup before the worktree is removed below */
      }
      return {
        outcome: "conflict",
        reason,
      };
    }
    const newHeadSha = run(worktreePath, ["rev-parse", "HEAD"]).trim();
    assertLiveWriteAllowed("git-push", `rebasing dirty fleet branch ${branch} for PR #${pr.prNumber}`);
    try {
      run(worktreePath, ["push", `--force-with-lease=${ref}:${pr.headSha}`, "origin", `HEAD:${ref}`]);
    } catch (error) {
      return {
        outcome: "lease-mismatch",
        reason:
          `force-with-lease refused ${branch}: expected ${pr.headSha}, attempted ${newHeadSha}; ` +
          capStderrExcerpt(spawnFailureText(error), STDERR_EXCERPT_CAP),
      };
    }
    const observedRemote = run(worktreePath, ["ls-remote", "origin", ref]).trim().split(/\s+/)[0];
    if (observedRemote !== newHeadSha) {
      return {
        outcome: "lease-mismatch",
        reason: `force-with-lease push reported success, but ${ref} reads ${observedRemote || "<absent>"} instead of ${newHeadSha}`,
      };
    }
    return { outcome: "rebased", oldHeadSha: pr.headSha, newHeadSha };
  } catch (error) {
    return {
      outcome: "error",
      reason: capStderrExcerpt(spawnFailureText(error), STDERR_EXCERPT_CAP),
    };
  } finally {
    if (worktreeCreated) {
      try {
        remove(repoDir, worktreePath);
      } catch {
        /* best-effort cleanup */
      }
    }
  }
}

/** W1-T11167: "regenerable" resolves registry-only conflicts (W1-T9578); "clean-merge" commits git's own clean merge.
 *  W1-T11170: "owned" is the deterministic tier on a fleet-owned or unheld operator-session head. */
export type ConflictRegenerationMode = "regenerable" | "clean-merge" | "owned";

/** W1-T11170: how one conflicted path was resolved by the deterministic tier. */
export type OwnedConflictPathMode = "take-main" | "regenerate" | "deleted-on-main";

/** W1-T11170: the head an "owned" round writes to, and for a session branch the ownership re-read run just before
 *  its push (a refusal reason, or undefined when the branch is still unheld). */
export interface OwnedConflictWrite {
  kind: OwnedConflictHeadKind;
  recheck?: () => string | undefined | Promise<string | undefined>;
}

export interface ConflictRegenerationOutcome {
  outcome: "pushed" | "fell-through" | "lease-mismatch" | "error";
  paths: Array<{ path: string; action: string; mode?: OwnedConflictPathMode }>;
  /** W1-T11167: the rename pairs between the merge base and main on paths the head changed. */
  renames?: Array<{ from: string; to: string }>;
  newHeadSha?: string;
  reason?: string;
  cleanupError?: string;
}

const inFlightConflictRegenerations = new Set<string>();

const conflictGardenHistorySteps = [CONFLICT_GARDEN_ACT, CONFLICT_GARDEN_VERIFIED, CONFLICT_GARDEN_JUDGED,
  CONFLICT_GARDEN_ESCALATED, "sweep.disposed", "sweep.merge_probe", PR_TERMINAL_STEP];
const conflictGardenHistory = createLedgerRotationMemo(rows => rows.filter(row =>
  typeof row.step === "string" && conflictGardenHistorySteps.includes(row.step)), {
  holder: "conflict-garden", pattern: /"step"\s*:\s*"(?:conflict_garden\.(?:act|verified|judged|escalated)|sweep\.(?:disposed|merge_probe)|pr\.terminal)"/,
});

async function readConflictGardenLedger(stateDir: string) {
  const result = await readLedgerUnionRecordsMemoized(stateDir, conflictGardenHistory, {
    step: conflictGardenHistorySteps, refuseIncomplete: true, rotationWindowMs: CONFLICT_GARDEN_WINDOW_MS,
  });
  if (!result.ok) throw new Error(`conflict gardening history is incomplete: ${result.unread.join(", ")}`);
  return result.rows;
}

async function conflictGardenEscalatedAtHead(stateDir: string, pr: OpenPrView): Promise<boolean> {
  const result = await ledgerRowsFor(stateDir, { steps: [CONFLICT_GARDEN_ESCALATED], prNumbers: [pr.prNumber] }, { refuseIncomplete: true });
  if (!result.ok) throw new Error(`conflict escalation history is incomplete: ${result.unread.join(", ")}`);
  return result.rows.some(row => row.head_sha === pr.headSha);
}

/** W1-T9578: git's blob id for `bytes`, in the object format `oid` is written in. */
function gitBlobId(bytes: Buffer, oid: string): string {
  return createHash(oid.length === 64 ? "sha256" : "sha1").update(`blob ${bytes.length}\0`).update(bytes).digest("hex");
}

/** Open each regular generator-copy leaf once: its type, mode and bytes share an identity. */
function readConflictRegularFile(path: string): { mode: number; bytes: Buffer } {
  const fd = fs.openSync(path, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW | fs.constants.O_NONBLOCK);
  try {
    const stat = fs.fstatSync(fd);
    if (!stat.isFile()) throw new Error(`conflict generator path is not a regular file: ${path}`);
    return { mode: stat.mode, bytes: readFileSync(fd) };
  } finally { fs.closeSync(fd); }
}

/** W1-T9578: after the sandboxed generators exit, compare their disposable copy with the merged tree the
 *  parent cut it from, by lstat and blob id, with NO Git in the copy (its repository is the generator's to
 *  rewrite). Its `.git` and the dependency links provisioned beside tracked paths are not compared. Returns
 *  each permitted path's bytes, a regular file reached only through real directories; throws, naming every
 *  path, when anything else changed, appeared or vanished, or a permitted path is missing or not a file. */
export function conflictGeneratorOutputs(copy: string, manifest: ReadonlyMap<string, { mode: string; oid: string }>,
  permitted: ReadonlySet<string>): Map<string, Buffer> {
  const trackedDirs = new Set<string>();
  for (const path of manifest.keys()) {
    for (let at = path.indexOf("/"); at >= 0; at = path.indexOf("/", at + 1)) trackedDirs.add(path.slice(0, at));
  }
  const outputs = new Map<string, Buffer>(), refused = new Set<string>(), seen = new Set<string>();
  const walk = (dir: string, prefix: string): void => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const rel = `${prefix}${entry.name}`, abs = join(dir, entry.name), tracked = manifest.get(rel);
      if (rel === ".git" || (entry.name === "node_modules" && !trackedDirs.has(rel) && tracked === undefined)) continue;
      if (entry.isDirectory()) {
        if (tracked !== undefined && tracked.mode !== "160000") refused.add(rel);
        if (tracked?.mode !== "160000") walk(abs, `${rel}/`);
        continue;
      }
      seen.add(rel);
      if (permitted.has(rel)) {
        if (!entry.isFile()) { refused.add(rel); continue; }
        outputs.set(rel, readConflictRegularFile(abs).bytes);
        continue;
      }
      let same = false;
      if (tracked !== undefined && entry.isSymbolicLink()) {
        same = tracked.mode === "120000" &&
          gitBlobId(Buffer.from(fs.readlinkSync(abs, { encoding: "buffer" })), tracked.oid) === tracked.oid;
      } else if (tracked !== undefined && entry.isFile() && tracked.mode !== "120000") {
        const file = readConflictRegularFile(abs);
        same = (tracked.mode === "100755") === ((file.mode & 0o100) !== 0) &&
          gitBlobId(file.bytes, tracked.oid) === tracked.oid;
      }
      if (!same) refused.add(rel);
    }
  };
  walk(copy, "");
  for (const [path, { mode }] of manifest) if (mode !== "160000" && !seen.has(path)) refused.add(path);
  for (const path of permitted) if (!outputs.has(path)) refused.add(path);
  if (refused.size > 0) {
    throw new Error(`conflict generator changed paths outside its registered outputs: ${[...refused].sort().join(", ")}`);
  }
  return outputs;
}

/** W1-T9578: write a copied-back artifact over its tracked path, never through a link. */
function writeRegisteredArtifact(worktree: string, path: string, bytes: Buffer): void {
  let dir = worktree;
  for (const part of path.split("/").slice(0, -1)) {
    dir = join(dir, part);
    if (!fs.lstatSync(dir).isDirectory()) throw new Error(`refusing to write ${path}: ${part} is not a directory`);
  }
  const fd = fs.openSync(join(worktree, path), fs.constants.O_WRONLY | fs.constants.O_TRUNC | fs.constants.O_NOFOLLOW);
  try {
    if (!fs.fstatSync(fd).isFile()) throw new Error(`refusing to write ${path}: not a regular file`);
    writeFileSync(fd, bytes);
  } finally { fs.closeSync(fd); }
}

export async function regenerateConflictViaGit(
  repoDir: string,
  worktreePath: string,
  pr: Pick<OpenPrView, "prNumber" | "headRefName" | "headSha" | "taskId">,
  mainSha: string,
  deps: Pick<BuildSweepEffectsDeps, "worktreeRemoveImpl"> & {
    git?: (cwd: string, args: readonly string[]) => string | Promise<string>;
    mode?: ConflictRegenerationMode;
    owned?: OwnedConflictWrite;
  } = {},
): Promise<ConflictRegenerationOutcome> {
  const cleanMerge = deps.mode === "clean-merge";
  const owned = deps.mode === "owned" ? deps.owned : undefined;
  const run = async (cwd: string, args: readonly string[]) => {
    if (deps.git) return deps.git(cwd, args);
    return hostWorktreeGitAsync(cwd, args, { maxBuffer: 1 << 24 });
  };
  const paths: ConflictRegenerationOutcome["paths"] = [];
  let followed: ConflictRegenerationOutcome["renames"];
  let created = false;
  const result = await (async (): Promise<ConflictRegenerationOutcome> => {
    try {
      if (deps.owned ? !pr.headRefName : deps.mode === "owned" ||
          !pr.taskId || !fixHeadAcceptable(pr.headRefName, pr.taskId, false)) {
        return { outcome: "fell-through", paths, reason: deps.mode === "owned"
          ? "an owned round names no head kind" : "head is not this task's run branch" };
      }
      const ref = `refs/heads/${pr.headRefName}`;
      const remoteRef = `refs/remotes/origin/${pr.headRefName}`;
      await run(repoDir, ["fetch", "--no-tags", "--quiet", "origin",
        "+refs/heads/main:refs/remotes/origin/main", `+${ref}:${remoteRef}`]);
      if ((await run(repoDir, ["rev-parse", remoteRef])).trim() !== pr.headSha ||
          (await run(repoDir, ["rev-parse", "origin/main"])).trim() !== mainSha) {
        return { outcome: "lease-mismatch", paths, reason: "head or main moved before conflict regeneration" };
      }
      mkdirSync(dirname(worktreePath), { recursive: true });
      await run(repoDir, ["worktree", "add", "--detach", worktreePath, pr.headSha]);
      created = true;
      let mergeError: string | undefined;
      try { await run(worktreePath, ["merge", "--no-edit", "--no-commit", mainSha]); }
      catch (error) {
        const reason = spawnFailureText(error);
        mergeError = reason;
      }
      const unmerged = [...new Set((await run(worktreePath, ["ls-files", "-u", "-z"])).split("\0")
        .filter(Boolean).map(entry => entry.slice(entry.indexOf("\t") + 1)))];
      if (cleanMerge) {
        // W1-T11167: git's own merge must already be the whole resolution: it exited 0, left nothing unmerged and
        // staged exactly the tree merge-tree computes for this head and main. Anything else is a conflict for a worker.
        const merged = unmerged.length === 0 && mergeError === undefined
          ? (await run(worktreePath, ["write-tree"])).trim() : undefined;
        const expected = merged === undefined ? undefined
          : (await run(worktreePath, ["merge-tree", "--write-tree", "--name-only", "--no-messages", pr.headSha, mainSha]))
            .split("\n")[0]!.trim();
        if (merged === undefined || merged !== expected) {
          await run(worktreePath, ["merge", "--abort"]);
          return { outcome: "fell-through", paths, reason: unmerged.length > 0
            ? `the local merge left unmerged paths: ${unmerged.join(", ")}`
            : mergeError ?? `the staged merge ${merged} is not git's merge-tree result ${expected}` };
        }
        const base = (await run(worktreePath, ["merge-base", pr.headSha, mainSha])).trim();
        const touched = new Set((await run(worktreePath, ["diff", "--name-only", "-z", base, pr.headSha]))
          .split("\0").filter(Boolean));
        const fields = (await run(worktreePath, ["diff", "--name-status", "-M", "-z", base, mainSha])).split("\0");
        const renames: Array<{ from: string; to: string }> = [];
        // Walk whole -z records (status, path, and a second path for R/C): a path such as README.md
        // must never be read as a status, or it consumes the real rename record after it.
        for (let at = 0; at < fields.length;) {
          const status = fields[at++]!;
          if (status === "") continue;
          const from = fields[at++]!;
          if (!/^[RC]/.test(status)) continue;
          const to = fields[at++]!;
          if (status.startsWith("R") && touched.has(from)) renames.push({ from, to });
        }
        followed = renames;
      } else if (unmerged.length === 0) {
        return { outcome: "error", paths, reason: mergeError === undefined
          ? "probe conflict no longer has unmerged paths" : mergeError };
      }
      if (owned) {
        // W1-T11170: per path, main's deletion, then the path's generator, then main's blob where the PR's change is
        // already on main byte for byte. Any other path aborts the whole merge for a worker round.
        const base = (await run(worktreePath, ["merge-base", pr.headSha, mainSha])).trim();
        const unresolved: string[] = [];
        const planned: Array<{ path: string; mode: OwnedConflictPathMode }> = [];
        for (const path of unmerged) {
          const present = (await run(worktreePath, ["ls-tree", "-r", "--name-only", "-z", mainSha, "--", path])).length > 0;
          if (!present) planned.push({ path, mode: "deleted-on-main" });
          else if (Object.hasOwn(REGENERABLE_ARTIFACT_GENERATORS, path)) planned.push({ path, mode: "regenerate" });
          else if (prChangeAlreadyOnMain(await run(worktreePath, ["diff", "--no-color", "--no-ext-diff", "-U0", base, pr.headSha, "--", path]),
            await run(worktreePath, ["show", `${mainSha}:${path}`]))) planned.push({ path, mode: "take-main" });
          else unresolved.push(path);
        }
        if (unresolved.length > 0) {
          await run(worktreePath, ["merge", "--abort"]);
          return { outcome: "fell-through", paths, reason: `unmerged paths no deterministic tier resolves: ${unresolved.join(", ")}` };
        }
        for (const { path, mode } of planned) {
          if (mode === "deleted-on-main") await run(worktreePath, ["rm", "--quiet", "--", path]);
          else await run(worktreePath, ["checkout", mainSha, "--", path]);
          paths.push({ path, action: mode === "regenerate" ? REGENERABLE_ARTIFACT_GENERATORS[path]! : mode, mode });
        }
      }
      const outside = owned ? [] : unmerged.filter(path => !Object.hasOwn(REGENERABLE_ARTIFACT_GENERATORS, path));
      if (outside.length > 0) {
        await run(worktreePath, ["merge", "--abort"]);
        return { outcome: "fell-through", paths, reason: `unmerged paths outside the registry: ${outside.join(", ")}` };
      }
      for (const path of owned ? [] : unmerged) {
        const present = (await run(worktreePath, ["ls-tree", "-r", "--name-only", "-z", mainSha, "--", path])).length > 0;
        if (!present) {
          await run(worktreePath, ["rm", "--", path]);
          paths.push({ path, action: "deleted-on-main" });
        } else {
          await run(worktreePath, ["checkout", mainSha, "--", path]);
          paths.push({ path, action: REGENERABLE_ARTIFACT_GENERATORS[path]! });
        }
      }
      const generated = paths.filter(({ action, mode }) => owned ? mode === "regenerate" : action !== "deleted-on-main");
      if (generated.length > 0) {
        // The generator never touches this worktree or its Git dirs: it runs in a disposable copy with a
        // private repository, and only the registered paths' bytes come back, read here by the parent.
        // Main's tree as a parentless root, then the merged tree on it, give that repository an origin/main
        // and a HEAD whose fetch carries two trees, never main's history.
        const tree = (await run(worktreePath, ["write-tree"])).trim();
        const base = (await run(worktreePath, ["commit-tree", `${mainSha}^{tree}`, "-m", "conflict generator base"])).trim();
        const input = (await run(worktreePath, ["commit-tree", tree, "-p", base, "-m", "conflict generator input"])).trim();
        const manifest = new Map((await run(worktreePath, ["ls-tree", "-r", "-z", "--full-tree", tree])).split("\0")
          .filter(Boolean).map(record => {
            const tab = record.indexOf("\t"), [mode, , oid] = record.slice(0, tab).split(" ");
            return [record.slice(tab + 1), { mode: mode!, oid: oid! }] as const;
          }));
        const outputs = await withTempDir("conflict-generator", async (scratch) => {
          const copy = join(scratch, "tree"), home = join(scratch, "home");
          mkdirSync(join(copy, ".git"), { recursive: true });
          mkdirSync(home);
          await run(copy, ["init", "--quiet"]);
          await run(copy, ["fetch", "--quiet", "--no-tags", pathToFileURL(realpathSync(repoDir)).href, input]);
          await run(copy, ["update-ref", "refs/remotes/origin/main", base]);
          await run(copy, ["checkout", "--quiet", "--detach", input]);
          const commonDir = (await run(copy, ["rev-parse", "--path-format=absolute", "--git-common-dir"])).trim();
          excludeNodeModulesFromGit(copy, { commonDir: () => commonDir });
          await provisionWorktreeNodeModules(repoDir, copy);
          const status = proofSandboxStatus();
          if (status.mode !== "bwrap") throw new Error(`conflict generator sandbox unavailable: ${status.reason}`);
          const sandbox = proofSandboxArgv({ cwd: copy, home });
          for (const { action } of generated) {
            await execFileRouted(status.binary, [...sandbox, "npm", "run", "--silent", action], {
              cwd: copy, env: { ...proofChildEnv(home), TMPDIR: "/tmp" }, encoding: "utf8",
            });
          }
          return conflictGeneratorOutputs(copy, manifest, new Set(generated.map(({ path }) => path)));
        });
        for (const [path, bytes] of outputs) {
          writeRegisteredArtifact(worktreePath, path, bytes);
          await run(worktreePath, ["add", "--", path]);
        }
        const staged = (await run(worktreePath, ["diff-index", "--cached", "--name-only", "-z", tree, "--"]))
          .split("\0").filter(Boolean).filter(path => !outputs.has(path));
        if (staged.length > 0) {
          return { outcome: "error", paths, reason: `generator copy-back staged unregistered paths: ${staged.join(", ")}` };
        }
      }
      const unexpected = (await run(worktreePath, ["diff", "--name-only", "-z"])).split("\0").filter(Boolean);
      if (unexpected.length > 0) {
        return { outcome: "error", paths, reason: `generator left unstaged edits: ${unexpected.join(", ")}` };
      }
      await run(worktreePath, ["commit", "-m", owned
        ? `fix(sweep): resolve merge conflicts with main on ${pr.headRefName}`
        : cleanMerge
        ? "fix(sweep): merge main where GitHub's merge reports a conflict git does not"
        : "fix(sweep): regenerate merge-conflicted artifacts", ...(pr.taskId ? ["-m", `Remudero-Task: ${pr.taskId}`] : [])]);
      const newHeadSha = (await run(worktreePath, ["rev-parse", "HEAD"])).trim();
      const observed = new Map((await run(worktreePath, ["ls-remote", "origin", ref, "refs/heads/main"]))
        .trim().split("\n").map(line => { const [sha, name] = line.split(/\s+/); return [name, sha]; }));
      if (observed.get(ref) !== pr.headSha || observed.get("refs/heads/main") !== mainSha) {
        return { outcome: "lease-mismatch", paths, reason: "head or main moved during conflict regeneration" };
      }
      await run(worktreePath, ["merge-base", "--is-ancestor", pr.headSha, newHeadSha]);
      if (deps.owned?.kind === "session") {
        // W1-T11170: a session branch takes only a merge commit (first parent the PR head); anything else is refused
        // before any ownership read or push.
        const parents = (await run(worktreePath, ["rev-list", "--parents", "-n", "1", newHeadSha])).trim().split(/\s+/);
        if (parents[1] !== pr.headSha || parents.length !== 3) {
          return { outcome: "error", paths, reason: `the session write is not a merge commit on ${pr.headSha}` };
        }
      }
      let held: string | undefined;
      try { held = await deps.owned?.recheck?.(); }
      catch (error) { held = `the ownership re-read failed: ${spawnFailureText(error)}`; }
      if (held !== undefined) return { outcome: "lease-mismatch", paths, reason: `ownership re-read before the push: ${held}` };
      assertLiveWriteAllowed("git-push", `regenerating conflicts on ${pr.headRefName}`);
      if (deps.owned?.kind === "session") {
        // A session branch is written by a plain push with no force flag of any kind, after the ownership read
        // above: an owner who pushed in between wins.
        try {
          if (deps.git) await run(worktreePath, ["push", "origin", `HEAD:${ref}`]);
          else await gitPushRunBranchAsync(worktreePath, { destination: pr.headRefName, expectedHeadSha: newHeadSha });
        }
        catch (error) { return { outcome: "lease-mismatch", paths, reason: spawnFailureText(error) }; }
        const landed = (await run(worktreePath, ["ls-remote", "origin", ref])).trim().split(/\s+/)[0];
        return landed === newHeadSha ? { outcome: "pushed", paths, newHeadSha }
          : { outcome: "lease-mismatch", paths, reason: `remote head after push is ${landed}, expected ${newHeadSha}` };
      }
      try {
        const lease = `--force-with-lease=${ref}:${pr.headSha}`;
        if (deps.git) await run(worktreePath, ["push", lease, "origin", `HEAD:${ref}`]);
        else await gitPushRunBranchAsync(worktreePath, {
          destination: pr.headRefName, expectedHeadSha: newHeadSha,
          exec: (file, args, opts) => worktreePushExecAsync(worktreePath)(file,
            [...args.slice(0, 3), lease, ...args.slice(3)], opts),
        });
      }
      catch (error) { return { outcome: "lease-mismatch", paths, reason: spawnFailureText(error) }; }
      const pushed = (await run(worktreePath, ["ls-remote", "origin", ref])).trim().split(/\s+/)[0];
      return pushed === newHeadSha ? { outcome: "pushed", paths, newHeadSha }
        : { outcome: "lease-mismatch", paths, reason: `remote head after push is ${pushed}, expected ${newHeadSha}` };
    } catch (error) {
      return { outcome: "error", paths, reason: capStderrExcerpt(spawnFailureText(error), STDERR_EXCERPT_CAP) };
    }
  })();
  if (created) {
    try {
      if (deps.worktreeRemoveImpl) deps.worktreeRemoveImpl(repoDir, worktreePath);
      else await worktreeRemoveAsync(repoDir, worktreePath);
    }
    catch (error) {
      const reason = spawnFailureText(error);
      result.cleanupError = reason;
    }
  }
  return followed === undefined ? result : { ...result, renames: followed };
}

/** W1-T11170: a claim's renewal instants and minting host from its commit chain's messages. Each renewal commit
 *  repeats the anchor's mint line above its own `renewed` line: one time per instant. */
function readClaimChain(log: string): { times: number[]; host?: string } {
  const times = [...new Set([...log.matchAll(/^(?:rmd-dispatch claim \d+@\S+|renewed \d+@\S+) (\S+)$/gm)]
    .map((m) => Date.parse(m[1]!)).filter(Number.isFinite))].sort((a, b) => a - b);
  const host = /^rmd-dispatch claim \d+@(\S+) \S+$/m.exec(log)?.[1];
  return host === undefined ? { times } : { times, host };
}

/**
 * W1-T11170: production's three ownership reads for an operator-session branch. (a) each refs/rmd-dispatch claim
 * for a task id the PR names, its mint and `renewed` times read down the claim's commit chain; (b) the branch's fix
 * claim lock and the task's inflight lock; (c) the committer times of the branch's own commits, with the trailing
 * window's session branches for the operator's p90 gap. A failed read leaves its field absent, which reads ambiguous.
 */
export async function readSessionOwnershipViaGit(
  repoDir: string,
  pr: Pick<OpenPrView, "headRefName" | "taskId" | "body">,
  opts: { nowMs: number; readLock: (key: string) => string | undefined; fixClaimKey: string;
    git?: (cwd: string, args: readonly string[]) => string | Promise<string>; windowDays?: number; ownedFixClaimRunId?: string },
): Promise<SessionOwnershipEvidence> {
  const run = async (args: readonly string[]) =>
    opts.git ? opts.git(repoDir, args) : hostWorktreeGitAsync(repoDir, args, { maxBuffer: 1 << 24 });
  const evidence: SessionOwnershipEvidence = { nowMs: opts.nowMs };
  const ids = [...new Set([pr.taskId, ...[...(pr.body ?? "").matchAll(/^Remudero-Task:\s*(\S+)\s*$/gm)].map((m) => m[1])]
    .filter((id): id is string => id !== undefined && TASK_ID_TRAILER_RE.test(id)))];
  try {
    const claims: NonNullable<SessionOwnershipEvidence["claims"]> = [];
    for (const id of ids) {
      const ref = `refs/rmd-dispatch/${id}`;
      const holder = (await run(["ls-remote", "origin", ref])).trim().split(/\s+/)[0];
      if (!holder) continue;
      await run(["fetch", "--quiet", "--no-write-fetch-head", "origin", ref]);
      const read = readClaimChain(await run(["log", "--format=%B", holder]));
      claims.push({ ref, renewalsMs: read.times, ...(read.host ? { holderKind: read.host } : {}) });
    }
    evidence.claims = claims;
    // The producer of the one-renewal fallback: the fleet's median renewal gap for claims of each holder kind (the
    // minting host), pooled over every claim on the remote with at least two renewals. A claim whose kind has no
    // measurable cadence keeps no median, so it still reads unreadable and escalates once.
    if (claims.length > 0) {
      try {
        const own = new Set(claims.map((c) => c.ref));
        const gapsByKind = new Map<string, number[]>();
        const pool = (host: string | undefined, times: readonly number[]) => {
          if (host === undefined) return;
          gapsByKind.set(host, [...(gapsByKind.get(host) ?? []), ...sortedGaps(times)]);
        };
        for (const c of claims) pool(c.holderKind, c.renewalsMs);
        const peers = (await run(["ls-remote", "origin", "refs/rmd-dispatch/*"])).trim().split("\n").filter(Boolean)
          .map((line) => line.split(/\s+/)).filter(([sha, name]) => sha && name && !own.has(name)).slice(0, 100);
        if (peers.length > 0) await run(["fetch", "--quiet", "--no-write-fetch-head", "origin", ...peers.map(([, name]) => name!)]);
        for (const [sha] of peers) {
          const peer = readClaimChain(await run(["log", "--format=%B", sha!]));
          pool(peer.host, peer.times);
        }
        for (const c of claims) {
          const median = c.holderKind === undefined ? undefined : quantile(gapsByKind.get(c.holderKind) ?? [], 0.5);
          if (median !== undefined) c.holderKindMedianGapMs = median;
        }
      } catch (error) {
        const reason = `claim cadence: ${capStderrExcerpt(spawnFailureText(error), 200)}`;
        (evidence.unreadable ??= []).push(reason);
      }
    }
  } catch (error) {
    // (a) stays absent, which sessionBranchUnheld reads as ambiguous, and the reason rides the evidence.
    const reason = `claim: ${capStderrExcerpt(spawnFailureText(error), 200)}`;
    (evidence.unreadable ??= []).push(reason);
  }
  try {
    const lock = opts.readLock(opts.fixClaimKey);
    const taskLock = pr.taskId ? opts.readLock(pr.taskId) : undefined;
    const runId = [lock, taskLock].find((held) => held !== opts.ownedFixClaimRunId && held?.startsWith("OPERATOR-"));
    // The worker round owns this exact fix claim itself. It is the sole lock exempted at its final
    // pre-push re-read; a replaced lock, task lock, or operator run remains visible as held.
    const otherFixClaim = lock !== opts.ownedFixClaimRunId ? lock : undefined;
    evidence.session = { ...(taskLock ? { inflightLock: taskLock } : {}), ...(runId ? { operatorRunId: runId } : {}),
      ...(otherFixClaim ? { fixClaimKey: opts.fixClaimKey } : {}) };
  } catch (error) {
    const reason = `session: ${capStderrExcerpt(spawnFailureText(error), 200)}`;
    (evidence.unreadable ??= []).push(reason);
  }
  try {
    const branch = pr.headRefName!;
    await run(["fetch", "--no-tags", "--quiet", "origin", "+refs/heads/main:refs/remotes/origin/main",
      `+refs/heads/${branch}:refs/remotes/origin/${branch}`]);
    const stamps = async (ref: string, extra: readonly string[] = []) =>
      (await run(["log", "--format=%ct", "-n", "200", ...extra, ref, "--not", "refs/remotes/origin/main"]))
        .split("\n").filter(Boolean).map((line) => Number(line) * 1000).filter(Number.isFinite);
    evidence.pushesMs = await stamps(`refs/remotes/origin/${branch}`);
    if (evidence.pushesMs.length < 3) {
      const refs = (await run(["for-each-ref", "--format=%(refname)", "--count=40", "--sort=-committerdate",
        "refs/remotes/origin/run-unfiled-*", "refs/remotes/origin/plan-file-*", "refs/remotes/origin/codex/"]))
        .split("\n").filter(Boolean);
      const gaps: number[] = [];
      for (const ref of refs) gaps.push(...sortedGaps(await stamps(ref, [`--since=${opts.windowDays ?? 30}.days`])));
      const p90 = quantile(gaps, 0.9);
      if (p90 !== undefined) evidence.operatorP90GapMs = p90;
    }
  } catch (error) {
    const reason = `pushes: ${capStderrExcerpt(spawnFailureText(error), 200)}`;
    (evidence.unreadable ??= []).push(reason);
    delete evidence.pushesMs;
  }
  return evidence;
}

