              const metadataChecks = metadataRedRuledOut(ledgerLines, pr) ? undefined : metadataOnlyRed(pr);
              // W1-T5544: set only when a body red with no deterministic cure carries stale-proof evidence —
              // the escalation below is then skipped and the PR falls through to the proof-repair route.
              let proofRepairRoute: ProofDiscriminationEvidence | undefined;
              if (metadataChecks) {
                const priorRepair = ledgerLines.find((line) =>
                  line.step === "sweep.disposed" && line.pr_number === pr.prNumber &&
                  line.head_sha === pr.headSha && JSON.stringify(line.metadata_red_checks) === JSON.stringify(metadataChecks) &&
                  (line.metadata_repair_outcome === "repaired" || line.metadata_repair_outcome === "escalated"));
                if (priorRepair) {
                  progressParkedReason = `metadata red already ${priorRepair.metadata_repair_outcome} at this head and red set; awaiting a fresh edited-event verdict`;
                  if (!await askProgress()) break;
                  proofRepairRoute = proofRepairRouteEvidence(pr);
                }
                const result: MetadataRepairResult = priorRepair
                  ? { repaired: false, notMetadata: true, reason: "progress judge released the metadata wait" }
                  : deps.repairMetadata
                  ? await deps.repairMetadata(pr, metadataChecks)
                  : { repaired: false, reason: "metadata repair effect is not wired" };
                if (result.noCure && !result.repaired && !result.notMetadata) {
                  // THE ROUTE, NOT THE QUESTION (W1-T5544). Fleet-authored heads only: an operator's PR keeps
                  // today's escalation. An unreadable author reads as not-fleet, never as fleet.
                  const staleEvidence = proofRepairRouteEvidence(pr);
                  if (staleEvidence && deps.readPlanRepairFacts) {
                    try {
                      if (isFleetAppAuthor((await deps.readPlanRepairFacts(pr)).authorLogin)) proofRepairRoute = staleEvidence;
                    } catch (e) {
                      log("sweep.proof_repair.facts_error", { pr_number: pr.prNumber, error: String((e as Error)?.message ?? e) });
                    }
                  }
                }
                const outcome = result.repaired
                  ? "repaired"
                  : result.notMetadata
                  ? "not-metadata"
                  : proofRepairRoute
                  ? "proof-repair"
                  : "escalated";
                extraDisposedFields = { metadata_red_checks: metadataChecks, metadata_repair_outcome: outcome };
                if (!result.notMetadata && !proofRepairRoute) {
                  if (!result.repaired) {
                    await deps.escalate(
                      pr,
                      `metadata-only required checks ${metadataChecks.join(", ")} need title/body repair: ${result.reason}`,
                      renderClarificationQuestion(pr, result.reason, pr.strikeHistory ?? []),
                    );
                  }
                  acted = false;
                  standDownReason = `metadata-only red ${outcome}: ${result.reason}; no fix worker dispatched`;
                  break;
                }
              }
              // W1-T13994: the gate's scope refusal is routed by its class. A fleet-authored head takes a fix round
              // whose prompt names each undeclared path by its kind; any other head (an unreadable author reads as
              // not-fleet) escalates once per head, naming the paths and the two cures.
              if (gateRefusalClass(pr) === SCOPE_EXCEEDED_GATE_REFUSAL) {
                const undeclared = gateScopeExceededPaths(pr);
                let statuses: readonly PrFileStatus[] | undefined;
                // The read errors ride this pass's own sweep.disposed row, never a step of their own.
                const readErrors: string[] = [];
                if (undeclared.length > 0 && deps.readPrFileStatuses) {
                  try {
                    statuses = await deps.readPrFileStatuses(pr);
                  } catch (e) {
                    // Not erased: the error rides this PR's sweep.disposed row as read_errors, and no split is claimed.
                    readErrors.push(`file statuses: ${String((e as Error)?.message ?? e)}`);
                  }
                }
                const split = splitScopeExceededPaths(undeclared, statuses);
                let fleetHead = false;
                if (deps.readPlanRepairFacts) {
                  try {
                    fleetHead = isFleetAppAuthor((await deps.readPlanRepairFacts(pr)).authorLogin);
                  } catch (e) {
                    // Not erased: recorded as read_errors; an unread author is treated as not the fleet's, so it escalates.
                    readErrors.push(`author: ${String((e as Error)?.message ?? e)}`);
                  }
                }
                const scopePaths = { new_on_head: split.newOnHead, existing_at_base: split.existingAtBase,
                  ...(readErrors.length > 0 ? { read_errors: readErrors } : {}) };
                if (!fleetHead) {
                  const asked = ledgerLines.some((line) => line.step === "sweep.disposed" && line.pr_number === pr.prNumber &&
                    line.head_sha === pr.headSha && line.scope_refusal_outcome === "escalated");
                  extraDisposedFields = { ...extraDisposedFields, scope_refusal_paths: scopePaths, scope_refusal_outcome: "escalated" };
                  const question = scopeExceededClarificationQuestion(pr, split);
                  if (!asked) await deps.escalate(pr, question.reviewerRequirement, question);
                  acted = false;
                  standDownReason = `${question.reviewerRequirement}; an operator-authored head is escalated, no fix worker dispatched`;
                  break;
                }
                extraDisposedFields = { ...extraDisposedFields, scope_refusal_paths: scopePaths, scope_refusal_outcome: "fix-round" };
                const constraint = scopeExceededFixConstraint(split);
                pr.pendingAnswer = { ...pr.pendingAnswer,
                  constraint: [pr.pendingAnswer?.constraint, constraint].filter(Boolean).join("\n\n") };
              }
              const roundHold = await readSweepPriorRoundHold(pr);
              const refusedSameRed = sameHeadRedFixRefusal(ledgerLines, pr);
              const scopeAmendment = ledgerLines.findLast(row => row.task_id === pr.taskId && row.step === "fix.scope_amendment" &&
                row.head_sha === pr.headSha && (row.pr_number === undefined || Number(row.pr_number) === pr.prNumber));
              // W1-T13865: an amendment recorded only by its URL is found by that URL, and one no pr.terminal row
              // names (reconciliation discovers only pr_url rows) by its live merge time.
              const amendmentUrl = scopeAmendment?.amendment_url ?? scopeAmendment?.amendmentUrl;
              const amendmentKey = prUrlKey(amendmentUrl)?.toLowerCase();
              const amendmentNumber = Number(scopeAmendment?.amendmentNumber ?? scopeAmendment?.amendment_number ??
                (typeof amendmentUrl === "string" ? /\/pull\/(\d+)$/.exec(amendmentUrl.trim())?.[1] : undefined));
              const amendmentTerminal: Record<string, unknown> | undefined = scopeAmendment ? ledgerLines.findLast(row =>
                row.step === PR_TERMINAL_STEP && (amendmentKey !== undefined && typeof row.pr_url === "string"
                  ? prUrlKey(row.pr_url)?.toLowerCase() === amendmentKey : Number(row.pr_number) === amendmentNumber)) : undefined;
              const pendingAmendment = scopeAmendment !== undefined &&
                ["created", "resumed", "branch_update_requested"].includes(String(scopeAmendment.outcome ?? scopeAmendment.kind)) &&
                !["merged", "closed"].includes(String(amendmentTerminal?.state));
              const liveAmendmentMerged = pendingAmendment && typeof amendmentUrl === "string" && readAmendmentMergedAt !== undefined &&
                typeof await readAmendmentMergedAt(amendmentUrl) === "string";
              const closedAmendment = amendmentTerminal?.state === "closed";
              if (scopeAmendment && closedAmendment && deps.fixProgressJudge) {
                progressParkedReason = `amendment-closed: scope amendment ${scopeAmendment.amendmentNumber ?? scopeAmendment.amendment_number} closed without merging`;
                const waited = ledgerLines.some(row => row.step === "sweep.disposed" && row.pr_number === pr.prNumber &&
                  row.head_sha === pr.headSha && row.stand_down_reason === progressParkedReason);
                if (!waited) { acted = false; standDownReason = progressParkedReason; break; }
                if (!await askProgress()) break;
              }
              if (scopeAmendment && pendingAmendment && !liveAmendmentMerged) {
                const reason = `fix report requests a scope amendment: ${refusedSameRed?.scopeAmendment ?? scopeAmendment.paths}`;
                // The amendment is already the requested remedy. Keep its contract latch while it is
                // pending, but ask a person only if the amendment writer ultimately refuses it.
                extraDisposedFields = { ...extraDisposedFields, scope_amendment_red_checks: redCheckNames(pr) };
                acted = false;
                const amended = await refreshAmendedContract(ledgerLines.filter((line) => line.step === "sweep.disposed" &&
                  line.pr_number === pr.prNumber && line.head_sha === pr.headSha && line.scope_amendment_red_checks !== undefined));
                if (amended !== undefined || !standDownForPriorRound(roundHold)) standDownReason = amended ?? reason;
                break;
              }
              if (scopeAmendment?.outcome === "refused") {
                progressParkedReason = `scope-amendment-refused: ${scopeAmendment.reason}: ${scopeAmendment.detail}`;
              }
              if (scopeAmendment?.outcome === "refused" && scopeAmendment.reason === "path-not-changed") {
                const paths = Array.isArray(scopeAmendment.paths) ? scopeAmendment.paths.join(", ") : scopeAmendment.detail;
                const constraint = `Scope amendment refused (path-not-changed): ${scopeAmendment.detail}; ` +
                  `make the edit to ${paths} and leave it saved and uncommitted, then report NEEDS_SCOPE`;
                pr.pendingAnswer = { ...pr.pendingAnswer,
                  constraint: [pr.pendingAnswer?.constraint, constraint].filter(Boolean).join("\n\n") };
              }
              // PR-13039: the fix rung stands down at a head whose round handed off NEEDS_DESIGN; the hold starts on
              // the contract that round worked on, so an amendment that answers it takes main into the branch.
              const designHandoff = ledgerLines.findLast((line) => line.step === "fix.needs_design" &&
                line.task_id === fixLedgerTaskIdFor(pr) && line.head_sha === pr.headSha);
              if (designHandoff) {
                extraDisposedFields = { ...extraDisposedFields, needs_design_hold: true };
                const amended = await refreshAmendedContract([{ progress_contract_revision: designHandoff.contract_revision },
                  ...ledgerLines.filter((line) => line.step === "sweep.disposed" && line.pr_number === pr.prNumber &&
                    line.head_sha === pr.headSha && line.needs_design_hold === true)]);
                if (amended !== undefined) {
                  standDownReason = amended;
                  break;
                }
              }
              if (refusedSameRed && fixRoundTally(ledgerLines, fixLedgerTaskIdFor(pr), pr.headSha).refusals.length === 0) {
                progressParkedReason = `fix commit refused at this head and red set (${refusedSameRed.reason}) — incomplete round history`;
                const waited = ledgerLines.some(row => row.step === "sweep.disposed" && row.pr_number === pr.prNumber &&
                  row.head_sha === pr.headSha && typeof row.stand_down_reason === "string" && row.stand_down_reason.includes("incomplete round history"));
                if (!waited) {
                  acted = false;
                  standDownReason = progressParkedReason;
                  break;
                }
                if (!await askProgress()) break;
              }
              // W1-T8042 — a PR whose every red is main-inherited stands down for main repair: no fix
              // strike, job re-run or base refresh. Re-derived each pass, so a changed signature releases it.
              const inheritedReds = mainInherited.standDown.get(pr.prNumber);
              if (inheritedReds) {
                acted = false;
                baseRedStandDownPrs.add(pr.prNumber);
                standDownReason = describeMainInherited(pr, inheritedReds);
                extraDisposedFields = { ...extraDisposedFields, red_cause: "main-inherited",
                  main_inherited: inheritedReds.map((red) => ({ red_signature: describeMainRed(red.red),
                    candidate_sha: red.candidateSha, pr_numbers: red.prs.map((p) => p.prNumber) })) };
                break;
              }
              // W1-T527 — classify the evidence in hand before selecting a worker.
              // Only base-caused and environment stand down here.
              const redCause = classifyRedCause(pr, openPrs);
              if (redCauseStandsDown(redCause)) {
                acted = false;
                standDownReason = describeRedCause(redCause, pr, openPrs);
                // W1-T2620 — THE BASE-CAUSED STAND-DOWN'S EXIT CONDITION; the classifier, its text
                // and the strike accounting are untouched. `main_tip_sha` rides THIS PR's own line
                // whenever this pass classified it base-caused and a tip was read — recorded on the
                // ORDINARY stand-down path too, so the next pass's fold has a baseline.
                if (redCause === "base-caused" && mainTipSha !== undefined) {
                  baseCausedMainTipSha = mainTipSha;
                  // `selectBaseCausedRelease` already picked AT MOST ONE PR for this pass, oldest
                  // activity first (design iii) — this PR releases only if it IS that winner.
                  if (baseCausedReleaseTarget?.prNumber === pr.prNumber && deps.releaseBaseCausedStandDown) {
                    // The "released" sentence is set ONLY once the effect is about to be attempted.
                    // Omitted, this PR falls through to the ordinary stand-down sentence: never a
                    // silent no-op, and never a "released" claim with no push behind it.
                    try {
                      await deps.releaseBaseCausedStandDown(pr, mainTipSha);
                      standDownReason =
                        `red cause: base-caused — released: main has advanced to ${mainTipSha} since ` +
                        `this head last stood down against an earlier tip; redriving through the ` +
                        `existing post-fix leaf (no strike spent)`;
                    } catch (e) {
                      // FAIL QUIET — NEVER LAUNDER A RED: a failed release leaves this PR standing
                      // down under the ordinary sentence, retried next pass; no strike was at stake.
                      log("sweep.base_caused_release.error", {
                        pr_number: pr.prNumber,
                        main_tip_sha: mainTipSha,
                        error: String((e as Error)?.message ?? e),
                      });
                    }
                  }
                }
                break;
              }
              // W1-T4351 — A RED MAIN ALSO CARRIES IS NOT THIS DIFF'S: wait while main is red, then admit a refresh.
              let baseRed = decideBaseRed(pr, mainLatestRun, baseRedHistory);
              if (baseRed.kind === "refresh") {
                await readRefreshHistory(pr);
                baseRed = decideBaseRed(pr, mainLatestRun, baseRedHistory);
              }
              if (baseRed.kind !== "own") {
                baseRedStandDownPrs.add(pr.prNumber);
                acted = false;
                const mainSha = mainLatestRun?.sha ?? "unread";
                // The red and the census belong to the run that decided main's state, which may be an
                // older main commit than the head when the head's own run carries no evidence yet.
                const decidedSha = mainLatestRun?.decidedBySha ?? mainSha;
                const row = { run_id: deps.runId, task_id: pr.taskId ?? "SWEEP", pr_number: pr.prNumber, pr_url: pr.prUrl, head_sha: pr.headSha, check_name: baseRed.check, main_sha: mainSha,
                  ...(decidedSha !== mainSha ? { main_decided_by_sha: decidedSha } : {}) };
                let refreshHold = refreshUnwired;
                // W1-T12945: a light pass takes the wired path up to the press, then hands the head to its admission.
                const handOff = handsRefreshToLightAdmission && baseRed.kind === "refresh";
                if (baseRed.kind === "refresh" && (deps.updateBranch || handOff)) {
                  const check = baseRed.check;
                  const admit = { pr, arm: "base-red" as const, heldSinceMs: heldSinceMs(pr), row: { ...row, step: BASE_RED_REFRESH_STEP } };
                  if ((await readRefreshHistory(pr)).source === "unreadable") {
                    // A handed head is assessed once per head and main, like a head the admission holds.
                    const clearance = handOff && clearedRefreshKeys.has(`${pr.prNumber}@${pr.headSha}@${mainSha}`) ? { refresh: true as const }
                      : await admissionClearance(pr, "base-red", (pr.ciFailures ?? []).map(failure => failure.name),
                        baseReproductionFiles(pr.ciFailures ?? []), mainSha);
                    if (!clearance.refresh) {
                      if (!handOff) refreshAdmission.refuse(admit, clearance.evidence);
                      standDownReason = `base red refresh refused: ${clearance.evidence} — ${clearance.reason}`;
                      break;
                    }
                  }
                  if (handOff) {
                    extraDisposedFields = { ...extraDisposedFields, [LIGHT_REFRESH_HANDOFF_FIELD]: { cause: BASE_RED_MAIN_GREEN_CAUSE,
                      ...(Number.isFinite(admit.heldSinceMs) ? { held_since: clockFromMillisFn(() => admit.heldSinceMs).iso() } : {}),
                      refresh_row: { ...admit.row, cause: BASE_RED_MAIN_GREEN_CAUSE } } };
                  }
                  const held = handOff ? LIGHT_REFRESH_HANDOFF_HOLD : refreshAdmission.hold(admit);
                  if (held === undefined) {
                    await refreshAdmission.enter({ ...admit, refresh: () => pressRefresh(pr, admit.row),
                      settle: (verdict) => admissionReasons.set(pr.prNumber, "outcome" in verdict
                        ? `base red: ${check} was held while main was red; main is green at ${mainSha}, so the branch refresh was requested (${verdict.outcome}) — no fix dispatched`
                        : `base red: ${check} was held while main was red; main is green, but ${verdict.hold} — no fix dispatched`) });
                    standDownReason = `base red: ${check} was held while main was red; main is green at ${mainSha} — queued for refresh admission, no fix dispatched`;
                    break;
                  }
                  refreshHold = held;
                }
                if (!baseRedHistory.stoodDown.has(`${pr.prNumber}@${pr.headSha}`)) appendLine(deps.ledgerPath, { ...row, step: BASE_RED_STOOD_DOWN_STEP });
                standDownReason = baseRed.kind === "refresh"
                  ? `base red: ${baseRed.check} was held while main was red; main is green, but ${refreshHold} — no fix dispatched`
                  : baseRed.check === RULE_CHECKS_CHECK && mainLatestRun?.ruleChecks?.state === "red"
                    ? `base red: rule-checks fails at main ${mainSha}: a probe reproduced ${mainLatestRun.ruleChecks.suites.join(", ")} there — not this diff's; no fix dispatched, the branch refreshes once main is green`
                  : mainLatestRun?.state === "red" && mainLatestRun.observedChecks !== undefined && !mainLatestRun.observedChecks.includes(baseRed.check)
                    ? `base red: ${baseRed.check} is absent from main's latest run (${decidedSha}), and main is red — no fix dispatched, the branch refreshes once main is green`
                    : mainLatestRun?.state === "red"
                      ? `base red: ${baseRed.check} also fails on main's latest run (${decidedSha}) — not this diff's; no fix dispatched, the branch refreshes once main is green`
                      : `base red: ${baseRed.check} was held while main was red; main is ${mainLatestRun?.state ?? "unread"} at ${mainSha}, not yet green — no fix dispatched, the branch refreshes once main is green`;
                break;
              }
              // W1-T12945: the light admission's refresh of this head took, so this view predates the head it produced.
              if (handsRefreshToLightAdmission && baseRedHistory.refreshed.has(`${pr.prNumber}@${pr.headSha}`) &&
                  ledgerLines.some((line) => line.step === BASE_RED_REFRESH_STEP && line.cause === BASE_RED_MAIN_GREEN_CAUSE &&
                    line.pr_number === pr.prNumber && line.head_sha === pr.headSha && line.outcome === "updated")) {
                baseRedStandDownPrs.add(pr.prNumber);
                acted = false;
                standDownReason = "base red: the light pass's refresh admission requested the branch refresh (updated) — awaiting the refreshed head, no fix dispatched";
                break;
              }
              // W1-T4586 — A LIVE RUN FOR THIS HEAD SUPERSEDES ITS RED. Runs on one head share the
              // ci-<pr> concurrency group, so re-queueing one run's job cancelled the other, and the
              // older run's aggregate "failure" (over shards the newer run cancelled) spent fix
              // strikes: an 18-shard ping-pong on #7333. While a run for the head is live, wait.
              if (pr.checksState === "red" && deps.liveCiRunForHead && (await deps.liveCiRunForHead(pr))) {
                acted = false;
                standDownReason = "another CI run for this head is still queued or in progress — waiting for its result, never re-queueing over it";
                break;
              }
              // W1-T1275 — CI-GATE'S OWN CONCLUDED VERDICT CAN GO STALE: a required sibling's
              // success can land AFTER the gate's run concluded and posted a terminal FAILURE.
              // Fires BEFORE `dispatchFix` so a stale verdict never spends a strike on a diff that
              // carries no defect. Bounded to AT MOST ONCE per (head, sibling-transition), and the
              // rollup is a FRESH read, never a field cached on `pr`.
              const ciGateRollup =
                isBlockedCi(pr) && deps.readCiGateRollup ? await deps.readCiGateRollup(pr) : undefined;
              const staleTransition = staleCiGateTransition(ciGateRollup);
              const timeoutShape = isBlockedCi(pr)
                ? classifyCiTimeoutNoVerdict(pr.ciFailures ?? [], pr.redRequiredChecks ?? [], (pr.cancelledRequiredChecks ?? []).map((c) => c.name))
                : undefined;
              if (staleTransition && (!timeoutShape || timeoutShape.notReady.includes(staleTransition.siblingName))) {
                acted = false;
                standDownReason = await redriveStaleCiGate(deps, pr, staleTransition, reaggregatedCiGateKeys);
                break;
              }
              let ciFailuresForFix = isBlockedCi(pr) ? pr.ciFailures ?? [] : [];
              let cancelledChecks = isBlockedCi(pr) ? pr.cancelledRequiredChecks ?? [] : [];
              if (ciGateRollup?.length) {
                const names = [...new Set([
                  ...(pr.redRequiredChecks ?? []),
                  ...ciFailuresForFix.map((failure) => failure.name),
                  ...cancelledChecks.map((check) => check.name),
                ])];
                const fresh = new Set(stillRedRequiredNames(names, ciGateRollup));
                ciFailuresForFix = ciFailuresForFix.filter((failure) => fresh.has(failure.name));
                cancelledChecks = cancelledChecks.filter((check) => fresh.has(check.name));
                if (names.length > 0 && fresh.size === 0) {
                  acted = false;
                  standDownReason = `fresh CI rollup: snapshot red checks ${names.join(", ")} are green or in flight — no requeue or fix strike`;
                  break;
                }
              }
              const timeout = classifyCiTimeoutNoVerdict(
                ciFailuresForFix, stillRedRequiredNames(pr.redRequiredChecks ?? [], ciGateRollup), cancelledChecks.map((c) => c.name));
              if (timeout) {
                acted = false;
                standDownReason = await applyCiTimeoutRefresh(deps, ledgerLines, pr, timeout,
                  deps.readCiGateRollup ? ciGateRollup ?? "unreadable" : "unread");
                break;
              }
              // W1-T3194 — A POSITIVELY IDENTIFIED CI-INFRASTRUCTURE FAILURE HAS NO DEFECT IN THE
              // DIFF. Use the SAME job-only effect and durable head/check bound as cancellations,
              // before any fix claim or worker strike. A generic 403 never reaches this branch.
              const infrastructureFailures = ciFailuresForFix.flatMap((failure) => {
                const signature = classifyCiInfrastructureFailure({
                  conclusion: failure.conclusion,
                  logTail: failure.logTail,
                });
                return signature ? [{ failure, signature }] : [];
              });
              if (infrastructureFailures.length > 0) {
                const { handledNames, outcomes } = await requeueInfrastructureFailures(pr, infrastructureFailures, ciGateRollup);
                ciFailuresForFix = ciFailuresForFix.filter((failure) => !handledNames.has(failure.name));
                if (ciFailuresForFix.length === 0) {
                  acted = false;
                  const reason = `failed CI infrastructure check(s): ${outcomes.join("; ")}`;
                  if (!standDownForPriorRound(roundHold, reason)) standDownReason = reason;
                  break;
                }
              }
              // W1-T1223 — A CANCELLED REQUIRED CHECK HAS NO DEFECT IN THE DIFF for a fix-rung
              // worker to read. Fires BEFORE `dispatchFix` so a PR whose ENTIRE red verdict is
              // cancellations never spends a strike on nothing.
              if (cancelledChecks.length > 0) {
                const outcomes: string[] = [];
                const latest = dedupeRollupByLatestAttempt(ciGateRollup ?? []);
                // Build fixes still receive legacy FAILURE posts. The snapshot selects the new CANCELLED path
                // even if the fresh rollup has just cleared one of the gates.
                const cancelledPosts = new Set(cancelledChecks.filter(check => pr.ciFailures?.some(f => cancelledPostFor(f, check))));
                // W1-T8040: cancelled checks whose own log proves a deterministic ceiling timeout; they stay
                // genuine failures for the ci-log fix path instead of earning a requeue.
                const deterministicTimeouts = new Set<string>();
                for (const check of cancelledChecks) {
                  const key = `${pr.headSha}@${check.name}`;
                  // W1-T2431: OR the ledger-derived reading with the surface-derived one — a re-run
                  // this fleet ledgered, OR one GitHub's `run_attempt` shows already happened (an
                  // operator's own, invisible to the ledger). This only widens the true case.
                  const alreadyRequeued = incidentHolds.fresh.get(key) !== (check.runAttempt ?? null) &&
                    (requeuedCheckKeys.has(key) || cancelledCheckAlreadyRequeuedFromSurface(check.runAttempt));
                  const decision = cancelledCheckRequeueDecision(alreadyRequeued);
                  const timeoutSignature = deterministicTimeoutSignature(ciFailuresForFix.find((f) => f.name === check.name)?.logTail);
                  if (decision.requeue && timeoutSignature !== undefined) {
                    deterministicTimeouts.add(check.name);
                    appendLine(deps.ledgerPath, {
                      run_id: deps.runId,
                      task_id: pr.taskId ?? "SWEEP",
                      step: "sweep.check_requeue.skipped",
                      pr_number: pr.prNumber,
                      head_sha: pr.headSha,
                      check_name: check.name,
                      reason: "deterministic-timeout",
                      signature: timeoutSignature,
                    });
                    outcomes.push(`not re-queued "${check.name}" (deterministic-timeout: ${timeoutSignature})`);
                    continue;
                  }
                  if (cancelledPosts.has(check) && ciGateRollup?.length && !confirmsPostedCancellation(check, latest)) {
                    outcomes.push(`producer cancellation for "${check.name}" is no longer confirmed — awaiting fresh CI`);
                    continue;
                  }
                  if (decision.requeue) {
                    // LEDGERED BEFORE THE CALL (inside `requeueCheckJob`). Not dry-run-guarded:
                    // reaching this line already proves `acted` was true, which `dryRun` forces false.
                    const result = await requeueCheckJob(deps, pr, check, checkDeferrals.get(key), ciGateRollup);
                    if (result.kind === "dispatched" || result.kind === "failed") requeuedCheckKeys.add(key);
                    if (result.escalate && deps.escalateCancelledCheck)
                      await deps.escalateCancelledCheck(pr, check, result.escalate, "requeue-deferral-backstop");
                    outcomes.push(result.note ?? `re-queued "${check.name}"`);
                  } else {
                    // W1-T8040: a second cancellation whose log still names the failure says so.
                    const reason = timeoutSignature === undefined ? decision.reason : `${decision.reason} — its log names: ${timeoutSignature}`;
                    if (deps.escalateCancelledCheck) await deps.escalateCancelledCheck(pr, check, reason, "cancelled-twice");
                    outcomes.push(`escalated "${check.name}" (${reason})`);
                  }
                }
                // A cancelled check carries no diff defect — when EVERY red required check named
                // this pass is a cancellation, stand down rather than burning a strike on nothing.
                // `acted` stays FALSE: claiming true would seed `prior.fixed`, dedupe the whole
                // disposition away, and stop this logic observing the second cancellation.
                const explained = new Set<CiFailure>();
                const aggregators = new Set<string>();
                for (const check of cancelledPosts) {
                  if (deterministicTimeouts.has(check.name) || !producerCancellationExplainsRed(check, latest)) continue;
                  aggregators.add(CI_GATE_CHECK_NAME);
                  const matrix = CI_MATRIX_AGGREGATORS.find(({ constituent }) => constituent.test(check.name));
                  if (matrix) aggregators.add(matrix.aggregator);
                  for (const f of ciFailuresForFix) {
                    const alias = cancelledPostFor(f, check);
                    if (alias && postedCancellationExplainsRed(alias, latest)) explained.add(f);
                  }
                }
                ciFailuresForFix = ciFailuresForFix.filter(f => !explained.has(f) && !aggregators.has(f.name));
                const genuineFailures = ciFailuresForFix.filter((f) =>
                  deterministicTimeouts.has(f.name) || !cancelledChecks.some(c => c.name === f.name &&
                    (!cancelledPosts.has(c) || (f.conclusion === "CANCELLED" && f.jobId === c.jobId && producerCancellationExplainsRed(c, latest)))));
                if (genuineFailures.length === 0) {
                  acted = false;
                  const reason = `cancelled required check(s): ${outcomes.join("; ")}`;
                  if (!standDownForPriorRound(roundHold, reason)) standDownReason = reason;
                  break;
                }
              }
              // W1-T5920 — a red check whose job requeue GitHub DEFERRED (a FLAKE round's rerun refused
              // while its run was in flight) is retried before any strike, bounded by the BACKSTOP.
              const deferredFailures = ciFailuresForFix.filter((f) => !cancelledChecks.some((c) => c.name === f.name) &&
                !requeuedCheckKeys.has(`${pr.headSha}@${f.name}`) && checkDeferrals.has(`${pr.headSha}@${f.name}`));
              if (deferredFailures.length > 0) {
                const notes: string[] = [];
                for (const failure of deferredFailures) {
                  const key = `${pr.headSha}@${failure.name}`;
                  const result = await requeueCheckJob(deps, pr, failure, checkDeferrals.get(key), ciGateRollup);
                  if (result.kind === "dispatched" || result.kind === "failed") requeuedCheckKeys.add(key);
                  if (result.escalate) await deps.escalate(pr, result.escalate, renderClarificationQuestion(pr, result.escalate, pr.strikeHistory ?? []));
                  notes.push(result.note ?? `${result.kind === "dispatched" ? "re-queued" : "requeue failed for"} "${failure.name}"`);
                }
                ciFailuresForFix = ciFailuresForFix.filter((f) => !deferredFailures.includes(f));
                if (ciFailuresForFix.length === 0) {
                  const retryReason = `deferred requeue: ${notes.join("; ")} — no fix strike`;
                  acted = false;
                  if (!standDownForPriorRound(roundHold, retryReason)) standDownReason = retryReason;
                  break;
                }
              }
              const logHolds = ciFailuresForFix.flatMap((f) => f.logUnavailable?.kind === "deferred" && Date.parse(f.logUnavailable.until) > now // expiring-fixture: exempt -- W1-T12713 runtime retry time, no blind round before it
                ? [`${f.name}: ${describeCiLogUnavailable(f.logUnavailable)}`] : []);
              if (logHolds.length > 0) { acted = false; standDownReason = `${logHolds.join("; ")} — no fix strike`; break; }
